    p.stdin.flush()

def recv(timeout=5):
    fd=p.stdout.fileno()
    end=time.time()+timeout
    buf=b''
    while time.time()<end:
        r,_,_=select.select([fd],[],[],0.1)
        if not r:
            continue
        chunk=os.read(fd, 1)
        if not chunk:
            break
        buf += chunk
        if b'\r\n\r\n' in buf:
            header, rest = buf.split(b'\r\n\r\n',1)
            length=None
            for line in header.decode(errors='replace').split('\r\n'):
                if line.lower().startswith('content-length:'):
                    length=int(line.split(':',1)[1].strip())
            if length is None:
                return ('bad-header', header.decode(errors='replace'))
            while len(rest) < length:
                more=os.read(fd, length - len(rest))
                if not more:
                    break
                rest += more
            return (header.decode(errors='replace'), rest[:length].decode(errors='replace'))
    return None

