/workspace/src/main.rs.content:
mod completions;
mod help;
mod json;
mod logging;
mod runtime;

use std::env;
use std::path::{Path, PathBuf};
use std::process;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Topic {
    Root,
    Check,
    Clean,
    Toolchain,
    ToolchainInstall,
    ToolchainUninstall,
    Completions,
    RootHelp,
    ToolchainHelp,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let bin = bin_name(args.first().map(String::as_str).unwrap_or("executable"));
    let code = run(&bin, &args[1..]);
    if code != 0 {
        process::exit(code);
    }
}

fn run(bin: &str, args: &[String]) -> i32 {
    let mut stdio = false;
    let mut version_requested = false;

    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "-h" || arg == "--help" {
            print!("{}", help::root(bin));
            return 0;
        }
        if arg == "-V" || arg == "--version" {
            version_requested = true;
            index += 1;
            continue;
        }
        if arg == "--stdio" {
            stdio = true;
            index += 1;
            continue;
        }
        if arg == "--quiet" {
            index += 1;
            continue;
        }
        if is_quiet_short(arg) {
            index += 1;
            continue;
        }

        return match arg.as_str() {
            "check" => handle_check(bin, &args[index + 1..]),
            "clean" => handle_clean(bin, &args[index + 1..]),
            "toolchain" => handle_toolchain(bin, &args[index + 1..]),
            "completions" => handle_completions(bin, &args[index + 1..]),
            "help" => handle_help(bin, Topic::Root, &args[index + 1..]),
            _ if arg.starts_with('-') => {
                eprint!("{}", help::unexpected_argument(bin, Topic::Root, arg, false));
                2
            }
            _ => {
                eprint!("{}", help::unrecognized_subcommand(bin, Topic::Root, arg));
                2
            }
        };
    }

    if version_requested {
        println!("{}", help::VERSION);
        return 0;
    }
    if stdio {
        return json::run_stdio_server();
    }

    help::print_banner();
    0
}

fn handle_check(bin: &str, args: &[String]) -> i32 {
    let mut path: Option<String> = None;

    for arg in args {
        if arg == "-h" || arg == "--help" {
            print!("{}", help::check(bin));
            return 0;
        }
        if arg == "--all-targets" || arg == "--all-features" {
            continue;
        }
        if arg.starts_with('-') {
            eprint!("{}", help::unexpected_argument(bin, Topic::Check, arg, true));
            return 2;
        }
        if path.is_some() {
            eprint!("{}", help::unexpected_argument(bin, Topic::Check, arg, false));
            return 2;
        }
        path = Some(arg.clone());
    }

    let target = path.unwrap_or_else(current_dir_display);
    runtime::check(&target)
}

fn handle_clean(bin: &str, args: &[String]) -> i32 {
    for arg in args {
        if arg == "-h" || arg == "--help" {
            print!("{}", help::clean(bin));
            return 0;
        }
        eprint!("{}", help::unexpected_argument(bin, Topic::Clean, arg, false));
        return 2;
    }

    runtime::clean();
    0
}

fn handle_toolchain(bin: &str, args: &[String]) -> i32 {
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if arg == "-h" || arg == "--help" {
            print!("{}", help::toolchain(bin));
            return 0;
        }

        return match arg.as_str() {
            "install" => handle_toolchain_install(bin, &args[index + 1..]),
            "uninstall" => handle_toolchain_uninstall(bin, &args[index + 1..]),
            "help" => handle_help(bin, Topic::Toolchain, &args[index + 1..]),
            _ if arg.starts_with('-') => {
                eprint!("{}", help::unexpected_argument(bin, Topic::Toolchain, arg, false));
                2
            }
            _ => {
                eprint!("{}", help::unrecognized_subcommand(bin, Topic::Toolchain, arg));
                2
            }
        };
    }

    0
}

fn handle_toolchain_install(bin: &str, args: &[String]) -> i32 {
    let mut path: Option<PathBuf> = None;
    let mut index = 0;

    while index < args.len() {
        let arg = &args[index];
        if arg == "-h" || arg == "--help" {
            print!("{}", help::toolchain_install(bin));
            return 0;
        }
        if arg == "--skip-rustowl-toolchain" {
            index += 1;
            continue;
        }
        if arg == "--path" {
            let Some(value) = args.get(index + 1) else {
                eprint!("{}", help::missing_path_value());
                return 2;
            };
            path = Some(PathBuf::from(value));
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--path=") {
            path = Some(PathBuf::from(value));
            index += 1;
            continue;
        }

        eprint!("{}", help::unexpected_argument(bin, Topic::ToolchainInstall, arg, false));
        return 2;
    }

    runtime::toolchain_install(path.as_deref(), false)
}

fn handle_toolchain_uninstall(bin: &str, args: &[String]) -> i32 {
    for arg in args {
        if arg == "-h" || arg == "--help" {
            print!("{}", help::toolchain_uninstall(bin));
            return 0;
        }
        eprint!(
            "{}",
            help::unexpected_argument(bin, Topic::ToolchainUninstall, arg, false)
        );
        return 2;
    }

    runtime::toolchain_uninstall()
}

fn handle_completions(bin: &str, args: &[String]) -> i32 {
    let mut shell: Option<String> = None;

    for arg in args {
        if arg == "-h" {
            print!("{}", help::completions_short(bin));
            return 0;
        }
        if arg == "--help" {
            print!("{}", help::completions_long(bin));
            return 0;
        }
        if arg.starts_with('-') {
            eprint!("{}", help::unexpected_argument(bin, Topic::Completions, arg, true));
            return 2;
        }
        if shell.is_some() {
            eprint!("{}", help::unexpected_argument(bin, Topic::Completions, arg, false));
            return 2;
        }
        if !completions::is_supported_shell(arg) {
            eprint!("{}", help::invalid_shell(arg));
            return 2;
        }
        shell = Some(arg.clone());
    }

    let Some(shell) = shell else {
        eprint!("{}", help::missing_shell(bin));
        return 2;
    };

    print!("{}", completions::script(&shell));
    0
}

fn handle_help(bin: &str, start: Topic, args: &[String]) -> i32 {
    if args.is_empty() {
        match start {
            Topic::Root => print!("{}", help::root(bin)),
            Topic::Toolchain => print!("{}", help::toolchain(bin)),
            _ => {}
        }
        return 0;
    }

    match resolve_help_path(start, args) {
        Ok(topic) => {
            print!("{}", help::topic_help(bin, topic));
            0
        }
        Err((topic, bad)) => {
            eprint!("{}", help::unrecognized_subcommand(bin, topic, bad));
            2
        }
    }
}

fn resolve_help_path(start: Topic, args: &[String]) -> Result<Topic, (Topic, &str)> {
    let mut current = start;

    for arg in args {
        let Some(next) = next_help_topic(current, arg) else {
            return Err((current, arg));
        };
        current = next;
    }

    Ok(current)
}

fn next_help_topic(current: Topic, arg: &str) -> Option<Topic> {
    match current {
        Topic::Root => match arg {
            "check" => Some(Topic::Check),
            "clean" => Some(Topic::Clean),
            "toolchain" => Some(Topic::Toolchain),
            "completions" => Some(Topic::Completions),
            "help" => Some(Topic::RootHelp),
            _ => None,
        },
        Topic::Toolchain => match arg {
            "install" => Some(Topic::ToolchainInstall),
            "uninstall" => Some(Topic::ToolchainUninstall),
            "help" => Some(Topic::ToolchainHelp),
            _ => None,
        },
        _ => None,
    }
}

fn current_dir_display() -> String {
    env::current_dir()
        .unwrap_or_else(|_| PathBuf::from("."))
        .display()
        .to_string()
}

fn bin_name(raw: &str) -> String {
    Path::new(raw)
        .file_name()
        .and_then(|value| value.to_str())
        .unwrap_or(raw)
        .to_string()
}

fn is_quiet_short(arg: &str) -> bool {
    arg.starts_with('-') && arg.len() > 1 && arg[1..].chars().all(|ch| ch == 'q')
}

