use crate::logging;
use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const TOOLCHAIN_TARGET: &str = "nightly-2025-06-20-x86_64-unknown-linux-gnu";
const TOOLCHAIN_URL: &str =
    "https://static.rust-lang.org/dist/2025-06-20/rustc-nightly-x86_64-unknown-linux-gnu.tar.gz";

pub fn check(target_display: &str) -> i32 {
    let runtime_root = default_runtime_root();
    let sysroot = sysroot_dir(&runtime_root);

    if !sysroot.exists() {
        logging::info(
            "rustowl::toolchain",
            "sysroot not found; start setup toolchain",
        );
        let code = toolchain_install(None, true);
        if code != 0 {
            logging::error("rustowl::toolchain", "()");
        }
        return code;
    }

    warn_missing_tool("cargo", &runtime_root);
    warn_missing_tool("rustowlc", &runtime_root);

    if !is_valid_analysis_target(target_display) {
        logging::warn(
            "rustowl::lsp::analyze",
            format!("Invalid analysis target: {target_display}"),
        );
        logging::error("rustowl", "Analyze failed");
        return 1;
    }

    logging::info("rustowl::lsp::backend", "wait 100ms for rust-analyzer");
    thread::sleep(Duration::from_millis(100));
    logging::info("rustowl::lsp::backend", "stop running analysis processes");
    logging::info("rustowl::lsp::backend", "start analysis");
    logging::info("rustowl::lsp::backend", "analyze 1 packages...");
    warn_missing_tool("rustowlc", &runtime_root);
    logging::info(
        "rustowl::lsp::analyze",
        format!("start analyzing {target_display}"),
    );
    eprintln!();
    eprintln!("thread 'tokio-runtime-worker' panicked at /workspace/src/lsp/analyze.rs:222:41:");
    eprintln!(
        "called `Result::unwrap()` on an `Err` value: Os {{ code: 2, kind: NotFound, message: \"No such file or directory\" }}"
    );
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    logging::error("rustowl", "Analyze failed");
    1
}

pub fn clean() {}

pub fn toolchain_install(path: Option<&Path>, _invoked_by_check: bool) -> i32 {
    let root = path
        .map(Path::to_path_buf)
        .unwrap_or_else(default_runtime_root);
    let sysroot = sysroot_dir(&root);
    let _ = fs::create_dir_all(&sysroot);

    logging::info("rustowl::toolchain", "start installing Rust toolchain...");

    let temp_dir = temp_dir_path();
    let _ = fs::create_dir_all(&temp_dir);
    logging::info(
        "rustowl::toolchain",
        format!("temp dir is made: {}", temp_dir.display()),
    );
    logging::info(
        "rustowl::toolchain",
        format!("start downloading {TOOLCHAIN_URL}..."),
    );
    logging::error("rustowl::toolchain", "failed to download tarball");
    logging::error(
        "rustowl::toolchain",
        format!(
            "reqwest::Error {{ kind: Request, url: \"{TOOLCHAIN_URL}\", source: hyper_util::client::legacy::Error(Connect, ConnectError(\"dns error\", Custom {{ kind: Uncategorized, error: \"failed to lookup address information: Temporary failure in name resolution\" }})) }}"
        ),
    );
    1
}

pub fn toolchain_uninstall() -> i32 {
    let sysroot = sysroot_dir(&default_runtime_root());
    if sysroot.exists() {
        let _ = fs::remove_dir_all(&sysroot);
        logging::info(
            "rustowl::toolchain",
            format!("remove sysroot: {}", sysroot.display()),
        );
    }
    0
}

fn warn_missing_tool(tool: &str, runtime_root: &Path) {
    let candidate = runtime_root.join("bin").join(tool);
    if !candidate.exists() {
        logging::warn("rustowl::toolchain", format!("{tool} not found; fallback"));
    }
}

fn is_valid_analysis_target(target_display: &str) -> bool {
    let path = Path::new(target_display);
    path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("rs")
}

fn default_runtime_root() -> PathBuf {
    let home = env::var_os("HOME").map(PathBuf::from).unwrap_or_else(|| PathBuf::from("."));
    home.join(".rustowl")
}

fn sysroot_dir(root: &Path) -> PathBuf {
    root.join("sysroot").join(TOOLCHAIN_TARGET)
}

fn temp_dir_path() -> PathBuf {
    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos() as u64
        ^ (std::process::id() as u64);
    let alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut suffix = String::new();
    for _ in 0..6 {
        seed ^= seed << 13;
        seed ^= seed >> 7;
        seed ^= seed << 17;
        let index = (seed as usize) % alphabet.len();
        suffix.push(alphabet[index] as char);
    }

    PathBuf::from(format!("/tmp/.tmp{suffix}"))
}

