use crate::help;
use std::io::{self, BufRead, BufReader, Read, Write};

#[derive(Clone, Debug)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(String),
    String(String),
    Array(Vec<JsonValue>),
    Object(Vec<(String, JsonValue)>),
}

pub fn run_stdio_server() -> i32 {
    help::print_banner();

    let stdin = io::stdin();
    let mut reader = BufReader::new(stdin.lock());
    let stdout = io::stdout();
    let mut writer = stdout.lock();

    let mut initialized = false;

    loop {
        let Some(body) = read_message(&mut reader) else {
            return 0;
        };

        let parsed = parse_json(&body);
        let response = match parsed {
            Ok(JsonValue::Object(fields)) => handle_message(&fields, &mut initialized),
            Ok(_) => Some(error_response(None, -32600, "Invalid request", None)),
            Err(_) => Some(error_response(None, -32700, "Parse error", None)),
        };

        if let Some(response) = response {
            if write_message(&mut writer, &response).is_err() {
                return 1;
            }
        }
    }
}

fn handle_message(fields: &[(String, JsonValue)], initialized: &mut bool) -> Option<String> {
    let id = fields.iter().find(|(key, _)| key == "id").map(|(_, value)| value);
    let method = fields
        .iter()
        .find(|(key, _)| key == "method")
        .and_then(|(_, value)| match value {
            JsonValue::String(text) => Some(text.as_str()),
            _ => None,
        });
    let params = fields.iter().find(|(key, _)| key == "params").map(|(_, value)| value);

    let Some(method) = method else {
        return Some(error_response(id, -32600, "Invalid request", None));
    };

    if !*initialized {
        if method == "initialize" {
            if *initialized {
                return Some(error_response(id, -32600, "Invalid request", None));
            }
            *initialized = true;
            return Some(initialize_response(id));
        }
        return Some(error_response(id, -32002, "Server not initialized", None));
    }

    match method {
        "initialize" => Some(error_response(id, -32600, "Invalid request", None)),
        "shutdown" => {
            if let Some(params) = params {
                Some(error_response(
                    id,
                    -32602,
                    &format!("Unexpected params: {}", params.to_compact()),
                    None,
                ))
            } else {
                Some(result_response(id, "null"))
            }
        }
        "exit" => None,
        "initialized"
        | "textDocument/didOpen"
        | "textDocument/didChange"
        | "textDocument/didSave"
        | "textDocument/didClose"
        | "workspace/didChangeWorkspaceFolders" => None,
        _ => {
            if id.is_some() {
                Some(error_response(
                    id,
                    -32601,
                    "Method not found",
                    Some(method),
                ))
            } else {
                None
            }
        }
    }
}

fn initialize_response(id: Option<&JsonValue>) -> String {
    let id = id.map(JsonValue::to_compact).unwrap_or_else(|| "null".to_string());
    format!(
        "{{\"jsonrpc\":\"2.0\",\"result\":{{\"capabilities\":{{\"textDocumentSync\":{{\"change\":2,\"openClose\":true,\"save\":true}},\"workspace\":{{\"workspaceFolders\":{{\"changeNotifications\":true,\"supported\":true}}}}}}}},\"id\":{id}}}"
    )
}

fn result_response(id: Option<&JsonValue>, result: &str) -> String {
    let id = id.map(JsonValue::to_compact).unwrap_or_else(|| "null".to_string());
    format!("{{\"jsonrpc\":\"2.0\",\"result\":{result},\"id\":{id}}}")
}

fn error_response(
    id: Option<&JsonValue>,
    code: i32,
    message: &str,
    data: Option<&str>,
) -> String {
    let id = id.map(JsonValue::to_compact).unwrap_or_else(|| "null".to_string());
    let mut error = format!(
        "{{\"code\":{code},\"message\":{}}}",
        json_string(message)
    );
    if let Some(data) = data {
        error.pop();
        error.push_str(&format!(",\"data\":{}}}", json_string(data)));
    }
    format!("{{\"jsonrpc\":\"2.0\",\"error\":{error},\"id\":{id}}}")
}

fn read_message<R: BufRead>(reader: &mut R) -> Option<String> {
    let mut content_length: Option<usize> = None;

    loop {
        let mut line = String::new();
        let bytes = reader.read_line(&mut line).ok()?;
        if bytes == 0 {
            return None;
        }
        if line == "\r\n" || line == "\n" {
            break;
        }

        let lower = line.to_ascii_lowercase();
        if lower.starts_with("content-length:") {
            let value = line.split_once(':')?.1.trim();
            content_length = value.parse::<usize>().ok();
        }
    }

    let length = content_length?;
    let mut buffer = vec![0u8; length];
    reader.read_exact(&mut buffer).ok()?;
    Some(String::from_utf8_lossy(&buffer).to_string())
}

fn write_message<W: Write>(writer: &mut W, body: &str) -> io::Result<()> {
    write!(writer, "Content-Length: {}\r\n\r\n{}", body.len(), body)?;
    writer.flush()
}

fn parse_json(input: &str) -> Result<JsonValue, String> {
    let mut parser = Parser::new(input);
    let value = parser.parse_value()?;
    parser.skip_ws();
    if parser.is_eof() {
        Ok(value)
    } else {
        Err("trailing characters".to_string())
    }
}

fn json_string(value: &str) -> String {
    let mut out = String::with_capacity(value.len() + 2);
    out.push('"');
    for ch in value.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

impl JsonValue {
    fn to_compact(&self) -> String {
        match self {
            JsonValue::Null => "null".to_string(),
            JsonValue::Bool(value) => value.to_string(),
            JsonValue::Number(value) => value.clone(),
            JsonValue::String(value) => json_string(value),
            JsonValue::Array(items) => {
                let parts: Vec<String> = items.iter().map(JsonValue::to_compact).collect();
                format!("[{}]", parts.join(","))
            }
            JsonValue::Object(fields) => {
                let parts: Vec<String> = fields
                    .iter()
                    .map(|(key, value)| format!("{}:{}", json_string(key), value.to_compact()))
                    .collect();
                format!("{{{}}}", parts.join(","))
            }
        }
    }
}

struct Parser<'a> {
    input: &'a [u8],
    index: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Self {
            input: input.as_bytes(),
            index: 0,
        }
    }

    fn parse_value(&mut self) -> Result<JsonValue, String> {
        self.skip_ws();
        match self.peek() {
            Some(b'n') => {
                self.expect_bytes(b"null")?;
                Ok(JsonValue::Null)
            }
            Some(b't') => {
                self.expect_bytes(b"true")?;
                Ok(JsonValue::Bool(true))
            }
            Some(b'f') => {
                self.expect_bytes(b"false")?;
                Ok(JsonValue::Bool(false))
            }
            Some(b'"') => self.parse_string().map(JsonValue::String),
            Some(b'[') => self.parse_array(),
            Some(b'{') => self.parse_object(),
            Some(b'-') | Some(b'0'..=b'9') => self.parse_number().map(JsonValue::Number),
            _ => Err("invalid value".to_string()),
        }
    }

    fn parse_object(&mut self) -> Result<JsonValue, String> {
        self.expect(b'{')?;
        let mut fields = Vec::new();
        self.skip_ws();
        if self.consume_if(b'}') {
            return Ok(JsonValue::Object(fields));
        }

        loop {
            let key = self.parse_string()?;
            self.skip_ws();
            self.expect(b':')?;
            let value = self.parse_value()?;
            fields.push((key, value));
            self.skip_ws();
            if self.consume_if(b'}') {
                break;
            }
            self.expect(b',')?;
        }

        Ok(JsonValue::Object(fields))
    }

    fn parse_array(&mut self) -> Result<JsonValue, String> {
        self.expect(b'[')?;
        let mut items = Vec::new();
        self.skip_ws();
        if self.consume_if(b']') {
            return Ok(JsonValue::Array(items));
        }

        loop {
            items.push(self.parse_value()?);
            self.skip_ws();
            if self.consume_if(b']') {
                break;
            }
            self.expect(b',')?;
        }

        Ok(JsonValue::Array(items))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.expect(b'"')?;
        let mut out = String::new();

        while let Some(byte) = self.next() {
            match byte {
                b'"' => return Ok(out),
                b'\\' => {
                    let Some(escaped) = self.next() else {
                        return Err("unterminated escape".to_string());
                    };
                    match escaped {
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\u{0008}'),
                        b'f' => out.push('\u{000c}'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => {
                            let digits = self.take(4).ok_or_else(|| "bad unicode".to_string())?;
                            let hex = std::str::from_utf8(digits).map_err(|_| "bad unicode".to_string())?;
                            let value = u16::from_str_radix(hex, 16).map_err(|_| "bad unicode".to_string())?;
                            let ch = char::from_u32(value as u32).ok_or_else(|| "bad unicode".to_string())?;
                            out.push(ch);
                        }
                        _ => return Err("bad escape".to_string()),
                    }
                }
                byte => out.push(byte as char),
            }
        }

        Err("unterminated string".to_string())
    }

    fn parse_number(&mut self) -> Result<String, String> {
        let start = self.index;
        self.consume_if(b'-');
        self.consume_digits();
        if self.consume_if(b'.') {
            self.consume_digits();
        }
        if matches!(self.peek(), Some(b'e') | Some(b'E')) {
            self.index += 1;
            if matches!(self.peek(), Some(b'+') | Some(b'-')) {
                self.index += 1;
            }
            self.consume_digits();
        }
        String::from_utf8(self.input[start..self.index].to_vec()).map_err(|_| "bad number".to_string())
    }

    fn consume_digits(&mut self) {
        while matches!(self.peek(), Some(b'0'..=b'9')) {
            self.index += 1;
        }
    }

    fn skip_ws(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\n' | b'\r' | b'\t')) {
            self.index += 1;
        }
    }

    fn expect(&mut self, byte: u8) -> Result<(), String> {
        if self.consume_if(byte) {
            Ok(())
        } else {
            Err("unexpected character".to_string())
        }
    }

    fn expect_bytes(&mut self, bytes: &[u8]) -> Result<(), String> {
        for &byte in bytes {
            self.expect(byte)?;
        }
        Ok(())
    }

    fn consume_if(&mut self, byte: u8) -> bool {
        if self.peek() == Some(byte) {
            self.index += 1;
            true
        } else {
            false
        }
    }

    fn take(&mut self, count: usize) -> Option<&'a [u8]> {
        if self.index + count > self.input.len() {
            return None;
        }
        let start = self.index;
        self.index += count;
        Some(&self.input[start..self.index])
    }

    fn next(&mut self) -> Option<u8> {
        let value = self.peek()?;
        self.index += 1;
        Some(value)
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.index).copied()
    }

    fn is_eof(&self) -> bool {
        self.index >= self.input.len()
    }
}

/workspace/src/help.rs.content:
use crate::Topic;

pub const VERSION: &str = "RustOwl v1.0.0-rc.1";

pub fn print_banner() {
    eprintln!("{VERSION}");
    eprintln!("This is an LSP server. You can use --help flag to show help.");
}

pub fn root(bin: &str) -> String {
    format!(
        "Usage: {bin} [OPTIONS] [COMMAND]\n\nCommands:\n  check        Check availability\n  clean        Remove artifacts from the target directory\n  toolchain    Install or uninstall the toolchain\n  completions  Generate shell completions\n  help         Print this message or the help of the given subcommand(s)\n\nOptions:\n  -V, --version   Print version\n  -q, --quiet...  Suppress output\n      --stdio     Use stdio to communicate with the LSP server\n  -h, --help      Print help\n"
    )
}

pub fn check(bin: &str) -> String {
    format!(
        "Check availability\n\nUsage: {bin} check [OPTIONS] [path]\n\nArguments:\n  [path]  The path of a file or directory to check availability\n\nOptions:\n      --all-targets   Run the check for all targets instead of current only\n      --all-features  Run the check for all features instead of the current active ones only\n  -h, --help          Print help\n"
    )
}

pub fn clean(bin: &str) -> String {
    format!(
        "Remove artifacts from the target directory\n\nUsage: {bin} clean\n\nOptions:\n  -h, --help  Print help\n"
    )
}

pub fn toolchain(bin: &str) -> String {
    format!(
        "Install or uninstall the toolchain\n\nUsage: {bin} toolchain [COMMAND]\n\nCommands:\n  install    Install the toolchain\n  uninstall  Uninstall the toolchain\n  help       Print this message or the help of the given subcommand(s)\n\nOptions:\n  -h, --help  Print help\n"
    )
}

pub fn toolchain_install(bin: &str) -> String {
    format!(
        "Install the toolchain\n\nUsage: {bin} toolchain install [OPTIONS]\n\nOptions:\n      --path <path>             Runtime directory path to install RustOwl toolchain\n      --skip-rustowl-toolchain  Install Rust toolchain only\n  -h, --help                    Print help\n"
    )
}

pub fn toolchain_uninstall(bin: &str) -> String {
    format!(
        "Uninstall the toolchain\n\nUsage: {bin} toolchain uninstall\n\nOptions:\n  -h, --help  Print help\n"
    )
}

pub fn completions_short(bin: &str) -> String {
    format!(
        "Generate shell completions\n\nUsage: {bin} completions <SHELL>\n\nArguments:\n  <SHELL>  The shell to generate completions for [possible values: bash, elvish, fish, powershell, zsh, nushell]\n\nOptions:\n  -h, --help  Print help (see more with '--help')\n"
    )
}

pub fn completions_long(bin: &str) -> String {
    format!(
        "Generate shell completions\n\nUsage: {bin} completions <SHELL>\n\nArguments:\n  <SHELL>\n          The shell to generate completions for\n\n          Possible values:\n          - bash:       Bourne Again `SHell` (bash)\n          - elvish:     Elvish shell\n          - fish:       Friendly Interactive `SHell` (fish)\n          - powershell: `PowerShell`\n          - zsh:        Z `SHell` (zsh)\n          - nushell:    Nushell\n\nOptions:\n  -h, --help\n          Print help (see a summary with '-h')\n"
    )
}

pub fn root_help(bin: &str) -> String {
    format!(
        "Print this message or the help of the given subcommand(s)\n\nUsage: {bin} help [COMMAND]...\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n"
    )
}

pub fn toolchain_help(bin: &str) -> String {
    format!(
        "Print this message or the help of the given subcommand(s)\n\nUsage: {bin} toolchain help [COMMAND]...\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n"
    )
}

pub fn topic_help(bin: &str, topic: Topic) -> String {
    match topic {
        Topic::Root => root(bin),
        Topic::Check => check(bin),
        Topic::Clean => clean(bin),
        Topic::Toolchain => toolchain(bin),
        Topic::ToolchainInstall => toolchain_install(bin),
        Topic::ToolchainUninstall => toolchain_uninstall(bin),
        Topic::Completions => completions_long(bin),
        Topic::RootHelp => root_help(bin),
        Topic::ToolchainHelp => toolchain_help(bin),
    }
}

pub fn unexpected_argument(bin: &str, topic: Topic, arg: &str, tip_for_positional: bool) -> String {
    let mut out = format!("error: unexpected argument '{arg}' found\n");
    if tip_for_positional && arg.starts_with('-') {
        out.push_str(&format!(
            "\n  tip: to pass '{arg}' as a value, use '-- {arg}'\n"
        ));
    }
    out.push('\n');
    out.push_str(&usage_line(bin, topic));
    out.push_str("\n\nFor more information, try '--help'.\n");
    out
}

pub fn unrecognized_subcommand(bin: &str, topic: Topic, arg: &str) -> String {
    format!(
        "error: unrecognized subcommand '{arg}'\n\n{}\n\nFor more information, try '--help'.\n",
        usage_line(bin, topic)
    )
}

pub fn missing_path_value() -> String {
    "error: a value is required for '--path <path>' but none was supplied\n\nFor more information, try '--help'.\n".to_string()
}

pub fn missing_shell(bin: &str) -> String {
    format!(
        "error: the following required arguments were not provided:\n  <SHELL>\n\n{}\n\nFor more information, try '--help'.\n",
        usage_line(bin, Topic::Completions)
    )
}

pub fn invalid_shell(value: &str) -> String {
    format!(
        "error: invalid value '{value}' for '<SHELL>'\n  [possible values: bash, elvish, fish, powershell, zsh, nushell]\n\nFor more information, try '--help'.\n"
    )
}

pub fn usage_line(bin: &str, topic: Topic) -> String {
    match topic {
        Topic::Root => format!("Usage: {bin} [OPTIONS] [COMMAND]"),
        Topic::Check => format!("Usage: {bin} check [OPTIONS] [path]"),
        Topic::Clean => format!("Usage: {bin} clean"),
        Topic::Toolchain => format!("Usage: {bin} toolchain [COMMAND]"),
        Topic::ToolchainInstall => format!("Usage: {bin} toolchain install [OPTIONS]"),
        Topic::ToolchainUninstall => format!("Usage: {bin} toolchain uninstall"),
        Topic::Completions => format!("Usage: {bin} completions <SHELL>"),
        Topic::RootHelp => format!("Usage: {bin} help [COMMAND]..."),
        Topic::ToolchainHelp => format!("Usage: {bin} toolchain help [COMMAND]..."),
    }
}

/workspace/src/logging.rs.content:
use std::process::Command;

pub fn info(target: &str, message: impl AsRef<str>) {
    log("INFO", target, message.as_ref());
}

pub fn warn(target: &str, message: impl AsRef<str>) {
    log("WARN", target, message.as_ref());
}

pub fn error(target: &str, message: impl AsRef<str>) {
    log("ERROR", target, message.as_ref());
}

fn log(level: &str, target: &str, message: &str) {
    eprintln!("{} {:<5} [{target}] {message}", timestamp(), level);
}

fn timestamp() -> String {
    let output = Command::new("date")
        .args(["-u", "+%Y-%m-%dT%H:%M:%S.%3NZ"])
        .output();

    if let Ok(output) = output {
        let text = String::from_utf8_lossy(&output.stdout);
        let trimmed = text.trim();
        if !trimmed.is_empty() {
            return trimmed.to_string();
        }
    }

    "1970-01-01T00:00:00.000Z".to_string()
}

