        p.stdin.write(f'Content-Length: {len(data)}\r\n\r\n'.encode()+data)
        p.stdin.flush()
    def recv(timeout=2):
        fd=p.stdout.fileno(); end=time.time()+timeout; buf=b''
        while time.time()<end:
            r,_,_=select.select([fd],[],[],0.1)
            if not r:
                continue
            ch=os.read(fd,1)
            if not ch:
                return None
            buf += ch
            if b'\r\n\r\n' in buf:
                header, rest = buf.split(b'\r\n\r\n',1)
                length=None
                for line in header.decode(errors='replace').split('\r\n'):
                    if line.lower().startswith('content-length:'):
                        length=int(line.split(':',1)[1].strip())
                while len(rest) < length:
                    rest += os.read(fd, length-len(rest))
                return header.decode(errors='replace') + '\n' + rest[:length].decode(errors='replace')
        return 'TIMEOUT'
    out=[]
